#!/usr/bin/env python3
"""Build and approve the assessment report on the modernization pull request.

build:   collect the two analyst comments, add the baseline test result, post one
         'Assessment report' comment, and write the same Markdown to a file and the job summary.
approve: record who approved the report in that comment and print the approver's login.

Usage:
  modernize_assessment.py build --pr 12 --plan docs/... --tests 4 --failures 0 --errors 1 --out report.md
  modernize_assessment.py approve --pr 12
Requires GH_TOKEN, GITHUB_REPOSITORY and GITHUB_RUN_ID.
"""
import argparse
import json
import os
import re
import subprocess
import sys

MARKER = "<!-- modernize-assessment -->"
ANALYSTS = [
    ("modernize-compat-analyst", "Source compatibility"),
    ("modernize-dependency-analyst", "Dependencies and build tooling"),
]


def gh(*args, stdin=None, check=True):
    result = subprocess.run(["gh", *args], input=stdin, capture_output=True, text=True, encoding="utf-8")
    if result.returncode != 0:
        if check:
            sys.exit(f"gh {' '.join(args)} failed: {result.stderr.strip()}")
        return None
    return result.stdout


def list_comments(repo, pr):
    out = gh("api", f"repos/{repo}/issues/{pr}/comments", "--paginate", "--jq", ".[] | {id, body}")
    return [json.loads(line) for line in out.splitlines() if line.strip()]


def find_analyst_comment(comments, workflow_id, run_id):
    # gh-aw removes HTML comments from agent output, so match the footer it adds itself.
    footer = f"gh-aw-agentic-workflow: {workflow_id},"
    mine = [c for c in comments if footer in c["body"]]
    this_run = [c for c in mine if f"id: {run_id}," in c["body"]]
    chosen = this_run or mine
    return max(chosen, key=lambda c: c["id"]) if chosen else None


def clean_agent_comment(body):
    keep = [line for line in body.splitlines() if not line.startswith("> Generated by") and not line.startswith("<!-- gh-aw-")]
    return "\n".join(keep).strip()


def render(plan, tests, failures, errors, run_url, sections):
    lines = [
        MARKER,
        "## Assessment report",
        "",
        f"Status: waiting for approval. No application file has changed. Open the [pipeline run]({run_url}), select Review deployments, and approve to start the upgrade. Reject stops the pipeline here.",
        "",
        f"Plan: `{plan}`",
        "",
        "### Baseline",
        "",
        f"JDK 8 on `main`: {tests} tests, {failures} failures, {errors} errors. The upgrade is compared with this result.",
    ]
    for (workflow_id, title), body in zip(ANALYSTS, sections):
        lines += ["", f"### {title}", "", f"From `{workflow_id}`.", "", body]
    lines += [
        "",
        "### After you approve",
        "",
        "| Step | Job | Changes |",
        "|---|---|---|",
        "| 1 | `modernize-build-upgrader` | Build files only: Java version, Spring Boot parent, dependency versions, Maven Wrapper if needed |",
        "| 2 | `modernize-code-fixer` | Source and test files, following the findings above |",
        "| 3 | `verify-build`, `verify-static` | JDK 21 build and tests compared with the baseline, version and namespace checks |",
        "| 4 | `modernize-conformance-reviewer` | Compares the result with the plan and this report |",
    ]
    return "\n".join(lines) + "\n"


def upsert_comment(repo, pr, body):
    existing = next((c for c in list_comments(repo, pr) if MARKER in c["body"]), None)
    if existing:
        gh("api", "-X", "PATCH", f"repos/{repo}/issues/comments/{existing['id']}", "-F", "body=@-", stdin=body)
    else:
        gh("api", "-X", "POST", f"repos/{repo}/issues/{pr}/comments", "-F", "body=@-", stdin=body)


def build(args):
    repo, run_id = os.environ["GITHUB_REPOSITORY"], os.environ["GITHUB_RUN_ID"]
    run_url = f"{os.environ.get('GITHUB_SERVER_URL', 'https://github.com')}/{repo}/actions/runs/{run_id}"
    comments = list_comments(repo, args.pr)
    sections = []
    for workflow_id, title in ANALYSTS:
        comment = find_analyst_comment(comments, workflow_id, run_id)
        if not comment:
            sys.exit(f"No comment from {workflow_id} on pull request #{args.pr}. The assessment cannot be reviewed without it.")
        sections.append(clean_agent_comment(comment["body"]))
    report = render(args.plan, args.tests, args.failures, args.errors, run_url, sections)
    upsert_comment(repo, args.pr, report)
    with open(args.out, "w", encoding="utf-8") as handle:
        handle.write(report)
    summary = os.environ.get("GITHUB_STEP_SUMMARY")
    if summary:
        with open(summary, "a", encoding="utf-8") as handle:
            handle.write(report)


def find_approver(repo, run_id):
    out = gh("api", f"repos/{repo}/actions/runs/{run_id}/approvals", check=False)
    try:
        approvals = [a for a in json.loads(out or "[]") if a.get("state") == "approved"]
        return approvals[-1]["user"]["login"]
    except (ValueError, KeyError, IndexError, TypeError):
        return None


def approve(args):
    repo, run_id = os.environ["GITHUB_REPOSITORY"], os.environ["GITHUB_RUN_ID"]
    approver = find_approver(repo, run_id)
    who = f"@{approver}" if approver else "a required reviewer"
    comment = next((c for c in list_comments(repo, args.pr) if MARKER in c["body"]), None)
    if not comment:
        sys.exit(f"No assessment report comment on pull request #{args.pr}.")
    status = f"Status: approved by {who}. The upgrade is running."
    body = re.sub(r"(?m)^Status:.*$", status, comment["body"], count=1)
    gh("api", "-X", "PATCH", f"repos/{repo}/issues/comments/{comment['id']}", "-F", "body=@-", stdin=body)
    print(approver or "a required reviewer")


def main():
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    b = sub.add_parser("build")
    b.add_argument("--pr", required=True)
    b.add_argument("--plan", required=True)
    b.add_argument("--tests", required=True)
    b.add_argument("--failures", required=True)
    b.add_argument("--errors", required=True)
    b.add_argument("--out", required=True)
    a = sub.add_parser("approve")
    a.add_argument("--pr", required=True)
    args = parser.parse_args()
    build(args) if args.command == "build" else approve(args)


if __name__ == "__main__":
    main()
